                "<b>Recursion Tree for $T(n) = 2T(n/2) + cn$ (Slides 1.39–1.51)</b>: At depth $d$, there are $2^d$ subproblems of size $n/2^d$, so each level costs $2^d \\cdot c(n/2^d) = cn$. The tree reaches leaves of size $1$ at depth $h = \\lg n$ ($n$ leaves costing $\\Theta(n)$). Summing across all $\\lg n + 1$ levels gives $T(n) = cn \\lg n + \\Theta(n) = \\mathbf{\\Theta(n \\lg n)}$ in all cases!"
