              "• <b>What `F2(A, l, mid, r)` does</b>: Computes the maximum sum of a contiguous subarray of `A[l..r]` that <b>crosses the midpoint `mid`</b> (`left_sum + right_sum`) by scanning from `mid` down to `l` and from `mid+1` up to `r` in $\\Theta(n)$ linear time.<br>• <b>What `F1(A, l, r)` does</b>: Solves the <b>Maximum Contiguous Subarray Problem</b> on `A[l..r]` using Divide-and-Conquer by taking the maximum of the best subarray in the left half (`left_best`), right half (`right_best`), and crossing the midpoint (`cross_best`).<br>• <b>Recurrence Equation</b>: $T(n) = 2T(n/2) + \\Theta(n)$ for $n > 1$, and $T(1) = \\Theta(1)$.<br>• <b>Time Complexity</b>: By Master Theorem Case 2 (or recursion tree), $T(n) = \\mathbf{\\Theta(n \\lg n)}$.",
