            "<b>Formal Specification of Sorting (Slide 1.5)</b>: <b>Input</b>: sequence $\\langle a_1, a_2, \\dots, a_n \\rangle$ of numbers. <b>Output</b>: permutation $\\langle a'_1, a'_2, \\dots, a'_n \\rangle$ such that $a'_1 \\le a'_2 \\le \\dots \\le a'_n$. Slide Example: Input $\\langle 8, 2, 4, 9, 3, 6 \\rangle \\rightarrow$ Output $\\langle 2, 3, 4, 6, 8, 9 \\rangle$.",
            "<b>Insertion Sort Mechanics & Loop Invariant (Slides 1.6–1.7)</b>: Sorts in-place ($O(1)$ extra space) by maintaining a sorted left subarray $A[1..j-1]$ and inserting $key = A[j]$ into its proper place by shifting larger elements right (`A[i+1] ← A[i]`).",
            "<b>Complete Slide Trace on $A = [8, 2, 4, 9, 3, 6]$ (Slides 1.8–1.18)</b>:<ul><li><b>$j=2$ ($key=2$)</b>: Shift $8$ right, write $2$ at $A[1] \\Rightarrow$ <code>[2, 8, 4, 9, 3, 6]</code>.</li><li><b>$j=3$ ($key=4$)</b>: Shift $8$ right, stop at $2 \\le 4$, write $4$ at $A[2] \\Rightarrow$ <code>[2, 4, 8, 9, 3, 6]</code>.</li><li><b>$j=4$ ($key=9$)</b>: $8 \\le 9$ immediately (0 shifts) $\\Rightarrow$ <code>[2, 4, 8, 9, 3, 6]</code>.</li><li><b>$j=5$ ($key=3$)</b>: Shift $9, 8, 4$ right, stop at $2 \\le 3$, write $3$ at $A[2] \\Rightarrow$ <code>[2, 3, 4, 8, 9, 6]</code>.</li><li><b>$j=6$ ($key=6$)</b>: Shift $9, 8$ right, stop at $4 \\le 6$, write $6$ at $A[4] \\Rightarrow$ <code>[2, 3, 4, 6, 8, 9]</code>.</li></ul>"
