          "h": "Kinds of Analysis, Machine-Independent Time & Θ-Notation (Slides 1.19–1.24)",
          "pts": [
            "<b>Three Kinds of Analyses (Slide 1.20)</b>:<ul><li><b>Worst-case $T(n)$ (Usually)</b>: Maximum time on any input of size $n$ (a hard upper-bound guarantee).</li><li><b>Average-case $T(n)$ (Sometimes)</b>: Expected time over all inputs of size $n$ under an explicit statistical distribution assumption (e.g., all $n!$ permutations equally likely).</li><li><b>Best-case $T(n)$ (Bogus as a guarantee)</b>: Minimum time on a single favorable input.</li></ul>",
            "<b>Asymptotic $\\Theta$-Notation (Slide 1.22)</b>: $\\Theta(g(n)) = \\{ f(n) : \\exists c_1, c_2, n_0 > 0 \\text{ such that } 0 \\le c_1 g(n) \\le f(n) \\le c_2 g(n) \\text{ for all } n \\ge n_0 \\}$. Drop low-order terms and ignore leading constants (e.g., $3n^3 + 90n^2 - 5n + 6046 = \\Theta(n^3)$).",
            "<b>Insertion Sort Cases (Slide 1.24)</b>:<ul><li><b>Worst Case (Reverse sorted)</b>: $T(n) = \\sum_{j=2}^n \\Theta(j) = \\Theta\\left(\\frac{n(n-1)}{2}\\right) = \\Theta(n^2)$.</li><li><b>Average Case (Random permutation)</b>: $T(n) = \\sum_{j=2}^n \\Theta(j/2) = \\Theta(n^2)$.</li><li><b>Best Case (Already sorted)</b>: $T(n) = \\sum_{j=2}^n \\Theta(1) = \\Theta(n)$.</li></ul>"
          ],
