          "Trace Insertion Sort step-by-step on A = [8, 2, 4, 9, 3, 6] and state its best, average, and worst-case complexities.",
          "• <b>Initial</b>: <code>[8, 2, 4, 9, 3, 6]</code><br>• <b>j=2 (key=2)</b>: <code>[2, 8, 4, 9, 3, 6]</code><br>• <b>j=3 (key=4)</b>: <code>[2, 4, 8, 9, 3, 6]</code><br>• <b>j=4 (key=9)</b>: <code>[2, 4, 8, 9, 3, 6]</code> (0 shifts)<br>• <b>j=5 (key=3)</b>: <code>[2, 3, 4, 8, 9, 6]</code><br>• <b>j=6 (key=6)</b>: <code>[2, 3, 4, 6, 8, 9]</code>.<br><b>Best-case</b>: $\\Theta(n)$ (already sorted); <b>Average-case</b>: $\\Theta(n^2)$; <b>Worst-case</b>: $\\Theta(n^2)$ (reverse sorted).",
