            "<b>Alternating Lucky & Unlucky Splits (Slide 5.33)</b>: $L(n) = 2U(n/2) + \\Theta(n)$ and $U(n) = L(n-1) + \\Theta(n) \\implies L(n) = 2(L(n/2 - 1) + \\Theta(n/2)) + \\Theta(n) = 2L(n/2 - 1) + \\Theta(n) = \\mathbf{\\Theta(n \\lg n)}$."
