              "ans": "Initial mod 11 values: <code>0→0, 30→8, 1→1, 55→0, 16→5, 28→6, 13→2, 9→9, 26→4</code>.<br>• <b>1. Linear Probing ($m=11$)</b>: <code>[0: 0, 1: 1, 2: 55, 3: 13, 4: 26, 5: 16, 6: 28, 7: -, 8: 30, 9: 9, 10: -]</code>.<br>• <b>2. Quadratic Probing ($m=11$)</b>: <code>55</code> ($h=0$, $0+1^2=1$ full, $0+2^2=4$) $\\to 4$; <code>26</code> ($h=4$, $4+1^2=5$ full, $4+2^2=8$ full, $4+3^2=13\\equiv 2$ full, $4+4^2=20\\equiv 9$ full, $4+5^2=29\\equiv 7$) $\\to 7$. Result: <code>[0: 0, 1: 1, 2: 13, 3: -, 4: 55, 5: 16, 6: 28, 7: 26, 8: 30, 9: 9, 10: -]</code>.<br>• <b>3. Double Hashing ($m=11$)</b>: <code>55</code> ($h_1=0, h_2=7-(55\\bmod 7)=1$): probes $0+1=1$ (full), $0+2=2$ $\\to$ lands at <code>2</code>! Result: <code>[0: 0, 1: 1, 2: 55, 3: 13, 4: 26, 5: 16, 6: 28, 7: -, 8: 30, 9: 9, 10: -]</code>.<br>• <b>4. Chaining ($m=11$)</b>: <code>0: [0, 55], 1: [1], 2: [13], 4: [26], 5: [16], 6: [28], 8: [30], 9: [9]</code>.",
