              "type": "mcq",
              "q": "<b>Q3 & Q8</b>: What are the worst-case and average-case time complexities of Merge Sort?",
              "o": [
                "O(N log N)",
                "O(N²)",
                "O(log N)",
                "O(log log N)"
              ],
              "a": 0,
